SET synchronous_commit = on;
SELECT 'init' FROM pg_create_logical_replication_slot('regression_slot', 'test_decoding');

CREATE TABLE stream_test(data text);

-- consume DDL
SELECT data FROM pg_logical_slot_get_changes('regression_slot', NULL, NULL, 'include-xids', '0', 'skip-empty-xacts', '1');

-- streaming test with sub-transaction
BEGIN;
savepoint s1;
SELECT 'msg5' FROM pg_logical_emit_message(true, 'test', repeat('a', 50));
INSERT INTO stream_test SELECT repeat('a', 2000) || g.i FROM generate_series(1, 35) g(i);
TRUNCATE table stream_test;
rollback to s1;
INSERT INTO stream_test SELECT repeat('a', 10) || g.i FROM generate_series(1, 20) g(i);
COMMIT;

SELECT data FROM pg_logical_slot_get_changes('regression_slot', NULL,NULL, 'include-xids', '0', 'skip-empty-xacts', '1', 'stream-changes', '1');

-- streaming test for toast changes
ALTER TABLE stream_test ALTER COLUMN data set storage external;
-- consume DDL
SELECT data FROM pg_logical_slot_get_changes('regression_slot', NULL, NULL, 'include-xids', '0', 'skip-empty-xacts', '1');

INSERT INTO stream_test SELECT repeat('a', 6000) || g.i FROM generate_series(1, 10) g(i);
SELECT data FROM pg_logical_slot_get_changes('regression_slot', NULL,NULL, 'include-xids', '0', 'skip-empty-xacts', '1', 'stream-changes', '1');

-- streaming test for toast with multi-insert
\COPY stream_test FROM STDIN
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
toasted-
\.

SELECT data FROM pg_logical_slot_get_changes('regression_slot', NULL,NULL, 'include-xids', '0', 'skip-empty-xacts', '1', 'stream-changes', '1');

/*
 * Test concurrent abort with toast data. When streaming the second insertion, we
 * detect that the subtransaction was aborted, and reset the transaction while having
 * the TOAST changes in memory, resulting in deallocating both decoded changes and
 * TOAST reconstruction data. Memory usage counters must be updated correctly.
 *
 * Set debug_logical_replication_streaming to 'immediate' to disable the transaction
 * status check happening before streaming the second insertion, so we can detect a
 * concurrent abort while streaming.
 */
SET debug_logical_replication_streaming = immediate;
BEGIN;
INSERT INTO stream_test SELECT repeat(string_agg(to_char(g.i, 'FM0000'), ''), 50) FROM generate_series(1, 500) g(i);
ALTER TABLE stream_test ADD COLUMN i INT;
SAVEPOINT s1;
INSERT INTO stream_test(data, i) SELECT repeat(string_agg(to_char(g.i, 'FM0000'), ''), 50), 1 FROM generate_series(1, 500) g(i);
ROLLBACK TO s1;
COMMIT;
SELECT count(*) FROM pg_logical_slot_get_changes('regression_slot', NULL, NULL, 'include-xids', '0', 'skip-empty-xacts', '1', 'stream-changes', '1');
RESET debug_logical_replication_streaming;

-- bug #19616
--
-- An aborted top-level transaction that is discarded at eviction must not
-- leave its subtransactions marked as streamed.  Otherwise, decoding its
-- abort record invokes the stream abort callback for a subtransaction the
-- output plugin has never seen, even though streaming was never requested.
-- The trailing committed transaction is required to flush the ROLLBACK
-- record; without it decoding would stop before reaching the abort.
BEGIN;
SAVEPOINT s;
INSERT INTO stream_test VALUES ('subxact-change');
RELEASE SAVEPOINT s;
INSERT INTO stream_test SELECT 'toplevel-change' || g.i FROM generate_series(1, 5000) g(i);
ROLLBACK;
INSERT INTO stream_test VALUES ('after-abort');
SELECT data FROM pg_logical_slot_get_changes('regression_slot', NULL, NULL, 'include-xids', '0', 'skip-empty-xacts', '1');

-- Verify that a transactional message emitted in a streamed subtransaction
-- is associated with the subtransaction's XID.
CREATE PUBLICATION stream_pub;
SELECT 'init' FROM pg_create_logical_replication_slot('regression_pgoutput_slot', 'pgoutput');
SET debug_logical_replication_streaming = immediate;
BEGIN;
SAVEPOINT sp;
SELECT 'msg_subxact' FROM pg_logical_emit_message(true, 'test', 'msg');
ROLLBACK TO SAVEPOINT sp;
COMMIT;

-- Check that the streamed MESSAGE ('M') carries the aborted subtransaction's
-- XID rather than the top-level XID: in pgoutput's wire format, 'M' stores
-- its 4-byte XID at bytes 2..5, while STREAM ABORT ('A') stores the top-level
-- XID at bytes 2..5 and the aborted subtransaction's XID at bytes 6..9.
WITH changes AS (
	SELECT data
	FROM pg_logical_slot_get_binary_changes('regression_pgoutput_slot', NULL, NULL,
		'proto_version', '2', 'publication_names', 'stream_pub',
		'messages', 'true', 'streaming', 'on')
)
SELECT substr(m.data, 2, 4) = substr(a.data, 6, 4) AS subxid_matches
FROM changes m, changes a
WHERE get_byte(m.data, 0) = ascii('M')
  AND get_byte(a.data, 0) = ascii('A');
RESET debug_logical_replication_streaming;
SELECT pg_drop_replication_slot('regression_pgoutput_slot');
DROP PUBLICATION stream_pub;

DROP TABLE stream_test;
SELECT pg_drop_replication_slot('regression_slot');
